import base64, hashlib, sys, os
OUTDIR = "bootstrap/parts"

# Offset=15: h1 (verified OK) + 4 sub-parts of h2, all with md5 checks
parts = [
    ("h1", "014714d372ad6c79f5fe5116e206dea6",
     ""),
    ("p1", "8c70bc8c5605adc9d6086c84aa42844a",
     ""),
    ("p2", "a8bcc4842b5ec2adbbba36b6c2c28241",
     ""),
    ("p3", "00516fdf52e9a4b1fab327f182bef102",
     ""),
    ("p4", "52ea652139fc0a7fa060891d28b2279a",
     ""),
]

full_b64 = ""
for label, expected_md5, text in parts:
    actual_md5 = hashlib.md5(text.encode()).hexdigest()
    if actual_md5 != expected_md5:
        print(f"FAIL {label}: expected={expected_md5} got={actual_md5}", file=sys.stderr)
        sys.exit(1)
    full_b64 += text
    print(f"OK {label} len={len(text)} md5={actual_md5}")

print(f"Full b64 length: {len(full_b64)}")
full_b64_md5 = hashlib.md5(full_b64.encode()).hexdigest()
if full_b64_md5 != "0ec5ffd237c97da96101f568d1c84668":
    print(f"FAIL full b64 md5: {full_b64_md5}", file=sys.stderr)
    sys.exit(1)
print(f"OK full b64 md5")

data = base64.b64decode(full_b64)
actual_data_md5 = hashlib.md5(data).hexdigest()
if actual_data_md5 != "6c16107e4767e800b31369042750231f" or len(data) != 5133:
    print(f"FAIL data decode: md5={actual_data_md5} len={len(data)}", file=sys.stderr)
    sys.exit(1)

with open(os.path.join(OUTDIR, "f_0015.bin"), "wb") as f:
    f.write(data)
print(f"OK offset=15 written: {len(data)} bytes md5={actual_data_md5}")
